mapper.select:
SELECT v.page_path, SUM(v.view_count) AS view_count, 0.0 AS percent
FROM (
    SELECT page_path, view_count FROM page_view_country_daily_stat
    WHERE stat_date >= DATE(#{startTime})
      AND stat_date < DATE(DATE_ADD(#{endTime}, INTERVAL 1 SECOND))
      AND country = #{country}
    UNION ALL
    SELECT page_path, COUNT(*) AS view_count FROM page_view_log
    WHERE visited_at >= #{startTime} AND visited_at < DATE_ADD(#{endTime}, INTERVAL 1 SECOND)
      AND COALESCE(NULLIF(country, ''), '未知') = #{country}
    GROUP BY page_path
) v GROUP BY v.page_path ORDER BY view_count DESC LIMIT #{limit}
